CREATE TYPE "constraint_type" AS ENUM (
  'hard',
  'soft'
);

CREATE TYPE "task_sub_type" AS ENUM (
  'one_off',
  'recurring'
);

CREATE TYPE "day_of_week_abbr" AS ENUM (
  'Mon',
  'Tue',
  'Wed',
  'Thu',
  'Fri',
  'Sat',
  'Sun'
);

CREATE TYPE "task_status" AS ENUM (
  'pending',
  'in_progress',
  'completed',
  'scheduled',
  'cancelled'
);

CREATE TABLE "Users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" VARCHAR(255) UNIQUE NOT NULL,
  "password_hash" VARCHAR(255) NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT (now())
);

CREATE TABLE "UserPreferences" (
  "preference_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER UNIQUE NOT NULL,
  "start_time" TIME NOT NULL,
  "end_time" TIME NOT NULL,
  "start_week_day" day_of_week_abbr NOT NULL,
  "updated_at" TIMESTAMP DEFAULT (now())
);

CREATE TABLE "Calendars" (
  "calendar_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "is_use" BOOLEAN NOT NULL DEFAULT false,
  "start_date" DATE NOT NULL,
  "created_at" TIMESTAMP NOT NULL DEFAULT (now())
);

CREATE TABLE "TaskCategories" (
  "category_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "name" VARCHAR(100) NOT NULL
);

CREATE TABLE "OneOffTasks" (
  "one_off_task_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "deadline" TIMESTAMP,
  "duration_minutes" INTEGER,
  "category_id" INTEGER,
  "constraint" constraint_type NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "description" TEXT,
  "created_at" TIMESTAMP NOT NULL DEFAULT (now()),
  "updated_at" TIMESTAMP DEFAULT (now())
);

CREATE TABLE "RecurringTasks" (
  "recurring_task_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "start_date" day_of_week_abbr NOT NULL,
  "end_date" day_of_week_abbr NOT NULL,
  "event_start_time" TIME NOT NULL,
  "event_end_time" TIME NOT NULL,
  "category_id" INTEGER,
  "constraint" constraint_type NOT NULL,
  "title" VARCHAR(255) NOT NULL,
  "description" TEXT,
  "created_at" TIMESTAMP NOT NULL DEFAULT (now()),
  "updated_at" TIMESTAMP DEFAULT (now())
);

CREATE TABLE "TaskInstances" (
  "instance_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "GAGeneration_id" INTEGER NOT NULL,
  "task_source_id" INTEGER NOT NULL,
  "task_source_type" task_sub_type NOT NULL,
  "scheduled_start_datetime" TIMESTAMP NOT NULL,
  "scheduled_end_datetime" TIMESTAMP NOT NULL,
  "status" task_status NOT NULL DEFAULT 'scheduled',
  "created_at" TIMESTAMP NOT NULL DEFAULT (now()),
  "updated_at" TIMESTAMP DEFAULT (now())
);

CREATE TABLE "GAGeneration" (
  "GAGeneration_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER NOT NULL,
  "calendar_id" INTEGER
);

CREATE INDEX ON "UserPreferences" ("user_id");

CREATE INDEX ON "Calendars" ("user_id");

CREATE INDEX ON "TaskCategories" ("user_id");

CREATE INDEX ON "OneOffTasks" ("user_id");

CREATE INDEX ON "OneOffTasks" ("category_id");

CREATE INDEX ON "OneOffTasks" ("deadline");

CREATE INDEX ON "RecurringTasks" ("user_id");

CREATE INDEX ON "RecurringTasks" ("category_id");

CREATE INDEX ON "RecurringTasks" ("start_date", "end_date");

CREATE INDEX ON "TaskInstances" ("user_id");

CREATE INDEX ON "TaskInstances" ("GAGeneration_id");

CREATE INDEX ON "TaskInstances" ("status");

CREATE INDEX ON "TaskInstances" ("user_id", "status");

CREATE INDEX ON "TaskInstances" ("task_source_id", "task_source_type");

CREATE INDEX ON "TaskInstances" ("scheduled_start_datetime");

CREATE INDEX ON "TaskInstances" ("scheduled_end_datetime");

CREATE INDEX ON "TaskInstances" ("scheduled_start_datetime", "scheduled_end_datetime");

COMMENT ON COLUMN "UserPreferences"."user_id" IS 'Enforces one-to-one with Users';

COMMENT ON COLUMN "UserPreferences"."start_week_day" IS 'e.g., Mon for Monday, Tue for Tuesday';

COMMENT ON COLUMN "UserPreferences"."updated_at" IS 'Keep track of the last update';

COMMENT ON COLUMN "OneOffTasks"."deadline" IS 'When the task must be completed by';

COMMENT ON COLUMN "OneOffTasks"."duration_minutes" IS 'Estimated time needed to complete the task, optional';

COMMENT ON COLUMN "RecurringTasks"."start_date" IS 'Day of week the recurrence happens';

COMMENT ON COLUMN "RecurringTasks"."end_date" IS 'Day of week the recurrence ends';

COMMENT ON COLUMN "RecurringTasks"."event_start_time" IS 'Time each recurring event instance starts';

COMMENT ON COLUMN "RecurringTasks"."event_end_time" IS 'Time each recurring event instance ends';

COMMENT ON COLUMN "TaskInstances"."task_source_id" IS 'ID of the source (OneOffTasks or RecurringTasks). FK constraint is polymorphic (see task_source_type) and cannot be drawn directly in standard DBML from a single column to multiple tables based on SQL standard.';

COMMENT ON COLUMN "TaskInstances"."task_source_type" IS 'Indicates if task_source_id refers to OneOffTasks (via "one_off") or RecurringTasks (via "recurring")';

ALTER TABLE "UserPreferences" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "Calendars" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "TaskCategories" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "OneOffTasks" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "OneOffTasks" ADD FOREIGN KEY ("category_id") REFERENCES "TaskCategories" ("category_id");

ALTER TABLE "RecurringTasks" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "RecurringTasks" ADD FOREIGN KEY ("category_id") REFERENCES "TaskCategories" ("category_id");

ALTER TABLE "TaskInstances" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "TaskInstances" ADD FOREIGN KEY ("GAGeneration_id") REFERENCES "GAGeneration" ("GAGeneration_id");

ALTER TABLE "GAGeneration" ADD FOREIGN KEY ("user_id") REFERENCES "Users" ("user_id");

ALTER TABLE "GAGeneration" ADD FOREIGN KEY ("calendar_id") REFERENCES "Calendars" ("calendar_id");



ALTER TABLE "UserPreferences"
ALTER COLUMN "start_time" SET DEFAULT '09:00';

ALTER TABLE "UserPreferences"
ALTER COLUMN "end_time" SET DEFAULT '21:00';

ALTER TABLE "UserPreferences"
ALTER COLUMN "start_week_day" SET DEFAULT 'Mon';
